function createStrategy() {
  // Build/upgrade/sell order found by offline hill-climbing over many seeds; executed in order, as gold allows.
  const SCRIPT = __SCRIPT__;
  const TYPES = { b: null };
  const COST = { bolt: 50, cannon: 90, frost: 70, lance: 120, flak: 80 };
  let ptr = 0;
  return {
    plan(s) {
      const acts = []; let g = s.gold;
      const occ = s.slots.map(x => x.turret ? { type: x.turret.type, tier: x.turret.tier, spent: x.turret.spent } : null);
      let guard = 0;
      while (ptr < SCRIPT.length && acts.length < 32 && guard++ < 200) {
        const e = SCRIPT[ptr];
        if (e[0] === 'b') {
          if (occ[e[1]]) { ptr++; continue; }
          if (g < COST[e[2]]) break;
          g -= COST[e[2]]; occ[e[1]] = { type: e[2], tier: 1, spent: COST[e[2]] };
          acts.push({ op: 'build', slot: e[1], type: e[2] }); ptr++;
        } else if (e[0] === 'u') {
          const t = occ[e[1]]; if (!t || t.tier >= 3) { ptr++; continue; }
          const c = COST[t.type] * (t.tier === 1 ? 1 : 2);
          if (g < c) break;
          g -= c; t.tier++; t.spent += c; acts.push({ op: 'upgrade', slot: e[1] }); ptr++;
        } else {
          const t = occ[e[1]]; if (!t) { ptr++; continue; }
          g += Math.floor(t.spent * 70 / 100); occ[e[1]] = null; acts.push({ op: 'sell', slot: e[1] }); ptr++;
        }
      }
      return acts;
    },
    target(t, c) {
      for (const e of c) if (e.type === 'mender') return e.id;          // menders first
      if (t.type === 'cannon' || t.type === 'flak') {                    // splash turrets: densest cluster
        const r2 = t.type === 'cannon' ? 8100 : 4900; let b = c[0], bs = -1;
        for (const e of c) {
          let n = 0;
          for (const o of c) { const dx = o.x - e.x, dy = o.y - e.y; if (dx * dx + dy * dy <= r2) n++; }
          if (n > bs || (n === bs && e.remaining < b.remaining)) { bs = n; b = e; }
        }
        return b.id;
      }
      return -1;                                                          // others: default (closest to base)
    }
  };
}

