for (const f of ['n11.txt', 'n22.txt', 'n33.txt', 'n44.txt']) {
  const tx = read(f).trim().split('\n'); const last = tx[tx.length - 1]; if (last[0] !== '[') { print(f, 'not done'); continue; }
  const sc = JSON.parse(last); const fn = opt.makeStrat(sc); let sum = 0, mn = 1e9;
  for (const sd of seeds) { const r = rampartSimulate(fn, sd, 12020).score; sum += r; mn = Math.min(mn, r); }
  print(f, (sum / seeds.length).toFixed(2), 'min', mn);
}

